class Solution:
    def minReadingSpeed(self, books: List[int], hours: int) -> int:
        s = 1
        while sum((p + s - 1) // s for p in books) > hours:
            s += 1
        return s

code.java:
class Solution {
    public int minReadingSpeed(int[] books, int hours) {
        for (int s = 1; ; s++) {
            long total = 0;
            for (int p : books) total += (p + (long) s - 1) / s;
            if (total <= hours) return s;
        }
    }
}

