code.python:
class Solution:
    def minReadingSpeed(self, books: List[int], hours: int) -> int:
        lo, hi = 1, max(books)
        while lo < hi:
            mid = (lo + hi) // 2
            needed = sum((p + mid - 1) // mid for p in books)
            if needed <= hours:
                hi = mid
            else:
                lo = mid + 1
        return lo

