class Solution {
    public int minReadingSpeed(int[] books, int hours) {
        int lo = 1, hi = 0;
        for (int p : books) hi = Math.max(hi, p);
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            long needed = 0;
            for (int p : books) needed += (p + (long) mid - 1) / mid;
            if (needed <= hours) hi = mid; else lo = mid + 1;
        }
        return lo;
    }
}

