int minReadingSpeed(int* books, int booksSize, int hours) {
    int lo = 1, hi = 0;
    for (int i = 0; i < booksSize; i++) if (books[i] > hi) hi = books[i];
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        long long needed = 0;
        for (int i = 0; i < booksSize; i++) needed += (books[i] + (long long) mid - 1) / mid;
        if (needed <= hours) hi = mid; else lo = mid + 1;
    }
    return lo;
}
